package comments

import (
	"bytes"
	"regexp"
)

// headerLines is how many of a file's first non-empty lines may hold a
// generated-file header.
const headerLines = 3

var (
	// generatorPhrase names a generator, as in "Code generated by", "This file
	// is automatically generated" or "Auto-generated from".
	generatorPhrase = regexp.MustCompile(`(?i)\b(code generated|auto-?generated|automatically generated|generated (by|from|with|using))\b`)
	// doNotEdit is the instruction a generator writes beside its name.
	doNotEdit = regexp.MustCompile(`(?i)\b(do not|don't) edit\b`)
	// generatedTag is the `@generated` marker several generators write alone.
	generatedTag = regexp.MustCompile(`(^|[^\w@])@generated\b`)
)

// generatedHeader reports whether the comments on a file's first non-empty
// lines say a generator owns the file: a generator phrase with an instruction
// not to edit, the `@generated` tag, or the language's own marker when it has
// one. Only comment text counts, so a string that quotes such a header is not
// one.
func generatedHeader(src []byte, units []unit, marker *regexp.Regexp) bool {
	var header []byte
	lines := 0
	for start := 0; start < len(src) && lines < headerLines; {
		end := bytes.IndexByte(src[start:], '\n')
		if end < 0 {
			end = len(src)
		} else {
			end += start
		}
		if len(bytes.TrimSpace(src[start:end])) > 0 {
			lines++
			for _, u := range units {
				if u.start < end && start < u.end {
					header = append(header, src[max(u.start, start):min(u.end, end)]...)
					header = append(header, '\n')
				}
			}
		}
		start = end + 1
	}
	if generatedTag.Match(header) || marker != nil && marker.Match(header) {
		return true
	}
	return generatorPhrase.Match(header) && doNotEdit.Match(header)
}
